    try{const data=await Promise.all([all('erp_customers'),all('erp_invoices'),all('erp_payments'),all('erp_customer_aliases')]);if(actor!==actorId()||epoch!==loadEpoch)return false;[state.customers,state.invoices,state.payments,state.aliases]=data;await readGoals(actor,epoch);if(actor!==actorId()||epoch!==loadEpoch)return false;loadedActor=actor;render();setStatus(`누적 계산서 ${state.invoices.filter(x=>x.status==='active').length}건 · 입금 ${state.payments.filter(x=>x.status!=='excluded').length}건`);return true;}catch(e){if(actor!==actorId()||epoch!==loadEpoch)return false;setStatus('ERP 조회 실패: '+(e.message||e)+' · 표시된 금액은 마지막 조회 기준입니다.',true);window.DF_DIAG?.error('ERP-LOAD','ERP 조회 실패',e.message||String(e));return false;}
