    const repCount=new Map();state.customers.forEach(c=>{const r=norm(c.representative);if(r)repCount.set(r,(repCount.get(r)||0)+1)});
    const dueMap=new Map(aggregate().map(g=>[g.c.customer_key,g.due]));
    const ranked=state.customers.map(c=>{let score=0,reasons=[];const name=norm(c.company_name),rep=norm(c.representative);if(name.length>=2&&dep===name){score+=420;reasons.push('업체명 정확히 일치')}else if(name.length>=3&&(hay.includes(name)||tokens.some(t=>t.length>=3&&(t.includes(name)||name.includes(t))))){score+=250;reasons.push('업체명 유사')}if(rep.length>=2&&repCount.get(rep)===1&&(dep===rep||tokens.includes(rep))){score+=190;reasons.push('고유 대표자명 일치')}if(score>0&&amount(p.amount)>0&&amount(dueMap.get(c.customer_key))===amount(p.amount)){score+=35;reasons.push('미수금액 일치')}return {key:c.customer_key,score,reason:reasons.join(' + ')}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);
