  document.addEventListener('keydown',event=>{const modal=modalStack.at(-1);if(!modal||modal.hidden)return;if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();modal._erpRequestClose?.();return;}if(event.key!=='Tab')return;const focusable=[...modal.querySelectorAll('button,input,select,textarea,a[href],[tabindex="0"]')].filter(x=>!x.disabled&&!x.hidden&&!x.closest('[hidden]')&&x.getClientRects().length);if(!focusable.length){event.preventDefault();modal.querySelector('[role="dialog"]')?.focus();return;}const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&(document.activeElement===first||!modal.contains(document.activeElement))){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||!modal.contains(document.activeElement))){event.preventDefault();first.focus();}},true);
